import numpy as np

# We need to solve: a^2 * b^2 = 16 * (5-a) * (5-b) * (a+b-5)
# Subject to a + b < 10 and a <= b

def check_constraint(a, b):
    if a <= 0 or b <= 0 or (a + b >= 10):
        return None # Invalid triangle/domain

    # Calculate the LHS and RHS
    LHS = a**2 * b**2
    RHS = 16 * (5 - a) * (5 - b) * (a + b - 5)

    # Check if they are close
    if LHS == RHS:
        c = 10 - a - b
        return (a, b, c)
    return None

# Grid search for a and b in the feasible region
# Since we checked the isosceles case (a=b) and found no solution, we check a range
# Let's focus the search around the near-integer values, e.g., 2 to 4 for a, and 2 to 8 for b.

a_vals = np.linspace(1.0, 3.0, 50)
b_vals = np.linspace(a_vals[0], 9.0, 50)

solutions = []

for a in a_vals:
    for b in b_vals:
        if a > b:
            continue
        if a + b >= 10:
            break

        solution = check_constraint(a, b)
        if solution:
            solutions.append(solution)

print("Found solutions (a, b, c):")
for sol in solutions:
    print(sol)
